const perfiles = {
  lento_demo: { batch_size: 1,   wait_ms: 1000, descripcion: 'Demo MUY lenta - 1 acta cada segundo, ~1.5h para 5351 actas' },
  demo:       { batch_size: 5,   wait_ms: 500,  descripcion: 'Demo en vivo - ~10 min, ves dashboard actualizar' },
  medio:      { batch_size: 25,  wait_ms: 200,  descripcion: 'Defensa estandar - ~2 min' },
  rapido:     { batch_size: 100, wait_ms: 0,    descripcion: 'Validacion - ~30 seg' },
  express:    { batch_size: 500, wait_ms: 0,    descripcion: 'Test maximo throughput - ~10 seg' }
};

const input = $input.first().json;
const perfilName = input.perfil_seleccionado || 'medio';
const perfil = perfiles[perfilName];

if (!perfil) {
  throw new Error('Perfil desconocido: ' + perfilName + '. Validos: ' + Object.keys(perfiles).join(', '));
}

const timestamp = new Date().toISOString().replace(/[:.]/g, '-');

return [{ json: {
  csv_path: '/output/transcripciones.csv',
  api_url: 'http://oficial_api:8000/api/v1/oficial/recuento',
  reset_url: 'http://oficial_api:8000/api/v1/oficial/admin/reset-actas?confirm=YES_DELETE_ALL',
  batch_size: perfil.batch_size,
  wait_ms: perfil.wait_ms,
  output_path: '/output/reporte-v2-' + perfilName + '-' + timestamp + '.json',
  perfil_activo: perfilName,
  perfil_descripcion: perfil.descripcion,
  truncar_antes: input.truncar_antes === true,
  timestamp_inicio: new Date().toISOString()
}}];

// Schema v2 del CSV: columnas en snake_case que ya coinciden con el
// payload del backend (sin apertura/cierre, con observacion_formal y
// tipo_observacion_formal). Defensa en profundidad: filtramos terminadores
// '0000000' aunque el extractor de CSVs ya los filtra.

const CODIGO_ACTA_RE = /^\d{13}$/;
const TIPOS_OBS_VALIDOS = new Set([
  'FALTA_DATOS_APERTURA_CIERRE',
  'MESA_LUGAR_DISTINTO',
  'USO_FORMULARIOS_NO_OFICIALES',
  'PAPELETAS_NO_AUTORIZADAS',
  'AUSENCIA_DELEGADOS',
  'FECHA_INCORRECTA',
  'ERRORES_TRANSCRIPCION',
  'FALTA_FIRMAS_HUELLAS',
  'INCONSISTENCIA_ARITMETICA',
]);

function toInt(s) {
  if (s === undefined || s === null) return null;
  const t = String(s).trim();
  if (t === '') return null;
  const v = parseFloat(t);
  if (Number.isNaN(v)) return null;
  return parseInt(v, 10);
}

function normalizarObs(s) {
  if (s === undefined || s === null) return null;
  const t = String(s).trim();
  return t === '' ? null : t;
}

function normalizarTipoObs(s) {
  const t = normalizarObs(s);
  if (t === null) return null;
  return TIPOS_OBS_VALIDOS.has(t) ? t : null;
}

const out = [];
const items = $input.all();

for (let idx = 0; idx < items.length; idx++) {
  const row = items[idx].json;
  const reasons = [];
  const csvRowNumber = idx + 2;

  const codigoActaInt = toInt(row.codigo_acta);
  let codigoActaStr;
  if (codigoActaInt === null) {
    reasons.push('codigo_acta no parseable');
    codigoActaStr = '0000000000000';
  } else {
    codigoActaStr = String(codigoActaInt);
    if (!CODIGO_ACTA_RE.test(codigoActaStr)) {
      reasons.push('codigo_acta no tiene 13 dígitos: ' + codigoActaStr);
    }
    if (codigoActaStr.endsWith('0000000')) {
      reasons.push('codigo_acta terminador 0000000 (placeholder del docente)');
    }
  }

  const codigoMesaInt = toInt(row.codigo_mesa);
  if (codigoMesaInt === null) reasons.push('codigo_mesa no parseable');

  const habilitados = toInt(row.habilitados);
  if (habilitados === null) reasons.push('habilitados no parseable');
  else if (habilitados <= 0) reasons.push('habilitados <= 0: ' + habilitados);

  const intFields = {
    votos_p1: toInt(row.votos_p1),
    votos_p2: toInt(row.votos_p2),
    votos_p3: toInt(row.votos_p3),
    votos_p4: toInt(row.votos_p4),
    blancos: toInt(row.blancos),
    nulos: toInt(row.nulos),
    anfora: toInt(row.anfora),
    no_usadas: toInt(row.no_usadas),
  };
  for (const [key, val] of Object.entries(intFields)) {
    if (val === null) reasons.push(key + ' no parseable');
  }

  const obsFormal = normalizarObs(row.observacion_formal);
  const tipoObsFormal = normalizarTipoObs(row.tipo_observacion_formal);

  const isInvalid = reasons.length > 0;

  const body = {
    codigo_acta: codigoActaInt === null ? 0 : codigoActaInt,
    codigo_mesa: codigoMesaInt === null ? 0 : codigoMesaInt,
    votos_p1: intFields.votos_p1 === null ? 0 : intFields.votos_p1,
    votos_p2: intFields.votos_p2 === null ? 0 : intFields.votos_p2,
    votos_p3: intFields.votos_p3 === null ? 0 : intFields.votos_p3,
    votos_p4: intFields.votos_p4 === null ? 0 : intFields.votos_p4,
    blancos: intFields.blancos === null ? 0 : intFields.blancos,
    nulos: intFields.nulos === null ? 0 : intFields.nulos,
    habilitados: habilitados === null || habilitados <= 0 ? 1 : habilitados,
    anfora: intFields.anfora === null ? 0 : intFields.anfora,
    no_usadas: intFields.no_usadas === null ? 0 : intFields.no_usadas,
  };
  if (obsFormal !== null) body.observacion_formal = obsFormal;
  if (tipoObsFormal !== null) body.tipo_observacion_formal = tipoObsFormal;

  out.push({
    json: {
      body: body,
      _invalid_local: isInvalid,
      _razones_pre_api: reasons,
      _csv_row_number: csvRowNumber,
      codigo_acta_csv: row.codigo_acta,
    },
  });
}

return out;

// Categorización defensiva basada en el comportamiento real del backend
// (recuento_router.py):
//   201 → INSERT_OK            (manejado en la rama OK)
//   404 → ERROR3               (mesa no existe en oficial.mesa)
//   409 → IDEMPOTENT_REPEAT    (Error4: codigo_acta UNIQUE ya presente)
//   422 con detail array       → ERROR1 o ERROR2 según texto
//   422 con detail dict/Pydantic → INCONSISTENCIA_NUMERICA
//                                  (ej: votos negativos rechazados por Field(ge=0))
//   5xx → ERROR_INFRA
//   otros → UNKNOWN_STATUS_<n>

const statusCode = $json.statusCode || 0;
const body = $json.body || {};
const bodyStr = JSON.stringify(body);
const codigoActa = $('Validar y construir body').item.json.body.codigo_acta;
const rowNumber = $('Validar y construir body').item.json._csv_row_number;
const razonesPreApi = $('Validar y construir body').item.json._razones_pre_api;
const invalidLocal = $('Validar y construir body').item.json._invalid_local;

let categoria;
let tipo_error = null;

if (invalidLocal) {
  categoria = 'INVALIDO_PRE_API';
} else if (statusCode === 404) {
  categoria = 'ERROR3_MESA_NO_EXISTE';
  tipo_error = 'ERROR3';
} else if (statusCode === 409) {
  categoria = 'IDEMPOTENT_REPEAT';
  tipo_error = 'ERROR4';
} else if (statusCode === 422) {
  const detail = body.detail;
  let isPydantic = false;
  if (Array.isArray(detail) && detail.length > 0 && typeof detail[0] === 'object') {
    isPydantic = true;
  }
  if (isPydantic) {
    categoria = 'INCONSISTENCIA_NUMERICA';
    tipo_error = 'INCONSISTENCIA_NUMERICA';
  } else if (bodyStr.indexOf('papeletas no usadas') >= 0) {
    categoria = 'ERROR1_BALANCE_PAPELETAS';
    tipo_error = 'ERROR1';
  } else if (bodyStr.indexOf('votos por partidos') >= 0 || bodyStr.indexOf('cantidad de boletas en el ánfora') >= 0) {
    categoria = 'ERROR2_BALANCE_VOTOS';
    tipo_error = 'ERROR2';
  } else {
    categoria = 'ERROR_VALIDACION_OTRO';
  }
} else if (statusCode >= 500) {
  categoria = 'ERROR_INFRA';
} else {
  categoria = 'UNKNOWN_STATUS_' + statusCode;
}

return {
  json: {
    codigo_acta: codigoActa,
    status: 'ERROR',
    _categoria_error: categoria,
    tipo_error: tipo_error,
    _csv_row_number: rowNumber,
    statusCode: statusCode,
    razon_api: bodyStr,
    razones_pre_api: JSON.stringify(razonesPreApi),
  }
};

const items = $input.all();
const total = items.length;
let ok = 0;
const porCategoria = {};
const ejemplosPorCategoria = {};
for (const item of items) {
  const cat = item.json._categoria_error || 'DESCONOCIDO';
  porCategoria[cat] = (porCategoria[cat] || 0) + 1;
  if (cat === 'INSERT_OK') ok++;
  if (cat !== 'INSERT_OK') {
    if (!ejemplosPorCategoria[cat]) ejemplosPorCategoria[cat] = [];
    if (ejemplosPorCategoria[cat].length < 3) {
      ejemplosPorCategoria[cat].push({
        codigo_acta: item.json.codigo_acta,
        statusCode: item.json.statusCode,
        razon_api: item.json.razon_api,
      });
    }
  }
}
const rechazados = total - ok;

const cfg = $('Configuración').first().json;
const inicio = cfg.timestamp_inicio;
const ahora = new Date().toISOString();
const duracionSeg = (new Date(ahora).getTime() - new Date(inicio).getTime()) / 1000;

const summary = {
  schema_version: 'v2',
  perfil_activo: cfg.perfil_activo,
  perfil_descripcion: cfg.perfil_descripcion,
  batch_size_usado: cfg.batch_size,
  wait_ms_usado: cfg.wait_ms,
  truncar_se_ejecuto: cfg.truncar_antes === true,
  timestamp_inicio: inicio,
  timestamp_fin: ahora,
  duracion_total_seg: Math.round(duracionSeg * 100) / 100,
  workflow_run_id: $execution.id,
  total: total,
  ok: ok,
  rechazados: rechazados,
  por_categoria: porCategoria,
  ejemplos_por_categoria: ejemplosPorCategoria,
  items: items.map(function (i) { return i.json; }),
};

const jsonStr = JSON.stringify(summary, null, 2);

return [{
  json: summary,
  binary: {
    data: {
      data: Buffer.from(jsonStr, 'utf8').toString('base64'),
      mimeType: 'application/json',
      fileName: 'reporte-v2.json',
    },
  },
}];
